/**
 * The live guide's record over days (SRS-RHB-018): per movement, how often it was practised with the guide, how many
 * attempts held the goal, and how many pulled too hard on the healthy side or moved another part of the face. For the
 * patient's week (재활 가이드) and the clinician summary.
 */
import type { LiveTaskId } from '../core';
import type { RehabLog } from '../data/types';

export interface BioTaskSummary {
  task: LiveTaskId;
  /** Guided exercises logged. */
  sessions: number;
  /** Reps (goal held) over all of them. */
  reps: number;
  /** Attempts, too strong and synkinetic attempts: only logs that recorded them (older logs kept reps only). */
  attempts: number;
  tooStrong: number;
  synk: number;
  /** Reps among the logs that recorded attempts (the share's numerator). */
  ratedReps: number;
  /** Best progress (share of the goal) and the goal of the latest log (share of the healthy side's range). */
  best: number;
  goal: number;
  /** Seconds held at the goal, over the logs that recorded it. */
  goodSec: number;
  /** Small movements seen with the healthy side still (SRS-RHB-019). */
  microEvents: number;
  /** Median of the logged exercise-time ratios (affected / healthy while moving); null without any (SRS-RHB-027). */
  ratio: number | null;
  /** The logged ratios themselves (for the median). */
  ratios: number[];
}

/** Share of attempts that held the goal; null without recorded attempts. */
export const repShare = (s: BioTaskSummary): number | null => (s.attempts > 0 ? Math.min(1, s.ratedReps / s.attempts) : null);

const ORDER: readonly LiveTaskId[] = ['brow', 'eyeClose', 'smile', 'snarl', 'pucker', 'cheekPuff'];

/** Guided exercises dated `from`..`to` (local dates, inclusive), per movement in face order. */
export function bioHistory(logs: readonly RehabLog[], from: string, to: string): BioTaskSummary[] {
  const by = new Map<LiveTaskId, BioTaskSummary>();
  const inRange = logs.filter((l) => l.bio && l.date >= from && l.date <= to).sort((a, b) => a.at.localeCompare(b.at));
  for (const l of inRange) {
    const b = l.bio!;
    const s = by.get(b.task) ?? {
      task: b.task,
      sessions: 0,
      reps: 0,
      attempts: 0,
      tooStrong: 0,
      synk: 0,
      ratedReps: 0,
      best: 0,
      goal: b.goal,
      goodSec: 0,
      microEvents: 0,
      ratio: null,
      ratios: [],
    };
    s.sessions += 1;
    s.reps += b.reps;
    if (typeof b.attempts === 'number') {
      s.attempts += b.attempts;
      s.ratedReps += b.reps;
      s.tooStrong += b.tooStrong ?? 0;
      s.synk += b.synk ?? 0;
    }
    s.goodSec += b.goodSec ?? 0;
    s.microEvents += b.microEvents ?? 0;
    s.best = Math.max(s.best, b.best);
    s.goal = b.goal;
    if (typeof b.ratioMed === 'number') {
      s.ratios.push(b.ratioMed);
      const xs = [...s.ratios].sort((x, y) => x - y);
      const m = xs.length >> 1;
      s.ratio = xs.length % 2 ? xs[m]! : (xs[m - 1]! + xs[m]!) / 2;
    }
    by.set(b.task, s);
  }
  return ORDER.flatMap((t) => (by.has(t) ? [by.get(t)!] : []));
}

/** The local date `days` before `ymd`. */
export function daysBefore(ymd: string, days: number): string {
  const d = new Date(`${ymd}T12:00:00`);
  d.setDate(d.getDate() - days);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

const pct = (x: number) => `${Math.round(x * 100)}%`;

/** One line per movement: practice, goal held, and what went wrong (Korean, for the screens and the summary). */
export function bioLine(s: BioTaskSummary): string {
  const share = repShare(s);
  const parts = [`${s.sessions}번`];
  if (share !== null) parts.push(`목표 유지 ${s.ratedReps}/${s.attempts}회(${pct(share)})`);
  else parts.push(`목표 유지 ${s.reps}회`);
  if (s.attempts > 0) {
    if (s.tooStrong) parts.push(`건강한 쪽 힘 과다 ${s.tooStrong}회`);
    if (s.synk) parts.push(`다른 곳 같이 움직임 ${s.synk}회`);
  }
  if (s.microEvents) parts.push(`작은 움직임 ${s.microEvents}회`);
  parts.push(`최고 목표의 ${pct(Math.min(s.best, 2))}`);
  // An observation during the exercise (small movements on purpose), not the assessment's ratio.
  if (s.ratio !== null) parts.push(`운동 중 마비 쪽 ${pct(s.ratio)}`);
  return parts.join(' · ');
}
